1	import java.util.List;
2	
3	/**
4	 * A class representing shared characteristics of consumers.
5	 *
6	 * @version 18.02.22 (DD:MM:YY)
7	 */
8	public abstract class Consumer extends Actor
9	{
10	    // Properties shared between all consumers:
11	    private static final int STARTING_SUSTENANCE_LEVEL = 30;
12	    private static final double NIGHT_PREY_MISS_PROBABILITY = 0.5;
13	
14	    // Properties unique to this consumer:
15	    private int breedingAge;
16	    private int sustenanceLevel;
17	    private int maxSustenanceLevel;
18	    private List<Class<?>> prey;
19	    private Disease disease;
20	    private boolean canEatCarcass;
21	
22	    /**
23	     * Create a new consumer at a location in the field.
24	     *
25	     * @param field               The field currently occupied.
26	     * @param location            The location within the field.
27	     * @param consumptionWorth    The worth of the consumer if consumed.
28	     * @param breedingProbability The likelihood of the consumer breeding.
29	     * @param maxBirthsAtOnce     The max number of births for the consumer.
30	     * @param maxAge              The age to which this consumer can live.
31	     * @param breedingAge         The age at which this consumer can start to breed.
32	     */
33	    public Consumer(Field field, Location location, List<Class<?>> prey, int consumptionWorth,
34	                    double breedingProbability, int maxBirthsAtOnce, int maxAge, int breedingAge,
35	                    int maxSustenanceLevel, boolean canEatCarcass)
36	    {
37	        super(field, location, consumptionWorth, breedingProbability, maxBirthsAtOnce,
38	              maxSustenanceLevel, maxAge);
39	        this.canEatCarcass = canEatCarcass;
40	        this.prey = prey;
41	        this.breedingAge = breedingAge;
42	        sustenanceLevel = STARTING_SUSTENANCE_LEVEL;
43	    }
44	
45	    /**
46	     * Create a new offspring of this consumer type at the given location.
47	     * Subclasses return an instance of their own concrete type.
48	     *
49	     * @param field    The field to place the offspring in.
50	     * @param location The location to place the offspring at.
51	     * @return A new offspring Consumer.
52	     */
53	    protected abstract Consumer createOffspring(Field field, Location location);
54	
55	    /**
56	     * Make this consumer act - that is: make it do
57	     * whatever it wants/needs to do.
58	     *
59	     * @param newConsumers A list to receive newly born consumers.
60	     */
61	    public void act(List<Actor> newConsumers)
62	    {
63	        incrementAge();
64	        if (!getIsAlive()) return;
65	        incrementHunger();
66	        if (!getIsAlive()) return;
67	        giveBirth(newConsumers);
68	        boolean wasPossibleToMove = huntForFood(newConsumers);
69	        if (hasDisease()) diseaseEffect();
70	        if (getIsAlive() && !wasPossibleToMove) setDead();
71	    }
72	
73	    /** @return True if this consumer is currently diseased. */
74	    private boolean hasDisease()
75	    {
76	        return disease != null;
77	    }
78	
79	    /** Mark this consumer as newly infected with a disease. */
80	    private void infect() { disease = new Disease(); }
81	
82	    /** Advance the disease by one step: progress timer, spread, then check lethality. */
83	    private void diseaseEffect()
84	    {
85	        disease.decrementStepsBeforeDeath();
86	        spreadDisease();
87	        checkForFatalDisease();
88	        incrementHunger();
89	    }
90	
91	    /** Resolve the disease if it has run its course. */
92	    private void checkForFatalDisease()
93	    {
94	        if (disease.diseaseFinished())
95	        {
96	            if (disease.isFatal())
97	            {
98	                setDead();
99	            }
100	            disease = null;
101	        }
102	    }
103	
104	    /** Spread the disease to all adjacent consumers of the same species. */
105	    private void spreadDisease()
106	    {
107	        Field field = getField();
108	        for (Location loc : field.adjacentLocations(getLocation()))
109	        {
110	            Object animal = field.getObjectAt(loc);
111	            if (animal != null && animal.getClass() == this.getClass())
112	            {
113	                ((Consumer) animal).infect();
114	            }
115	        }
116	    }
117	
118	    /** Hunt for food by moving toward it. */
119	    private boolean huntForFood(List<Actor> newActors)
120	    {
121	        Location newLocation = findFood(newActors);
122	
123	        if (newLocation == null)
124	        {
125	            newLocation = getField().freeAdjacentLocation(getLocation());
126	        }
127	
128	        if (newLocation != null) setLocation(newLocation);
129	
130	        return newLocation != null;
131	    }
132	
133	    /**
134	     * Set the starting age of the consumer, dependent on whether a random
135	     * age has been selected.
136	     *
137	     * @param randomAge If true, the age is random, otherwise it's 0.
138	     */
139	    protected void setStartingAge(boolean randomAge)
140	    {
141	        if (randomAge) setCurrentAge(rand.nextInt(getMaxAge()));
142	        else           setCurrentAge(0);
143	    }
144	
145	    /**
146	     * Check whether or not this consumer is to give birth at this step.
147	     * New births will be made into free adjacent locations.
148	     *
149	     * @param newConsumers A list to return newly born consumers.
150	     */
151	    private void giveBirth(List<Actor> newConsumers)
152	    {
153	        if (!checkForValidMate()) return;
154	
155	        Field field = getField();
156	        List<Location> free = field.getFreeAdjacentLocations(getLocation());
157	
158	        int births = breed();
159	        for (int b = 0; b < births && !free.isEmpty(); b++)
160	        {
161	            Location location = free.remove(0);
162	            newConsumers.add(createOffspring(field, location));
163	        }
164	    }
165	
166	    /**
167	     * @return True if there is a valid mate in an adjacent location for the consumer.
168	     */
169	    private boolean checkForValidMate()
170	    {
171	        Field field = getField();
172	
173	        for (Location location : field.adjacentLocations(getLocation()))
174	        {
175	            Object object = field.getObjectAt(location);
176	
177	            if (object instanceof Consumer other
178	                && other.getClass() == this.getClass()
179	                && other.canBreed()
180	                && other.getGender() != getGender())
181	            {
182	                return true;
183	            }
184	        }
185	
186	        return false;
187	    }
188	
189	    /**
190	     * Generate a number representing the number of births,
191	     * if it can breed.
192	     *
193	     * @return The number of births (may be zero).
194	     */
195	    private int breed()
196	    {
197	        boolean willBreed = rand.nextDouble() <= getBreedingProbability();
198	        return (canBreed() && willBreed) ? rand.nextInt(getMaxBirthsAtOnce()) + 1 : 0;
199	    }
200	
201	    /**
202	     * A consumer can breed if it has reached the breeding age.
203	     *
204	     * @return True if the consumer can breed, false otherwise.
205	     */
206	    private boolean canBreed() { return getCurrentAge() >= breedingAge; }
207	
208	    /**
209	     * Make this consumer more hungry. This could result in the consumer's death.
210	     */
211	    private void incrementHunger()
212	    {
213	        sustenanceLevel--;
214	        if (sustenanceLevel <= 0) setDead();
215	    }
216	
217	    /**
218	     * Look for prey adjacent to the current location.
219	     * Only the first live prey is eaten.
220	     *
221	     * @return Where food was found, or null if it wasn't.
222	     */
223	    private Location findFood(List<Actor> newActors)
224	    {
225	        Field field = getField();
226	
227	        for (Location where : field.adjacentLocations(getLocation()))
228	        {
229	            Object object = field.getObjectAt(where);
230	
231	            for (Class<?> preyClass : prey)
232	            {
233	                if (preyClass.isInstance(object))
234	                {
235	                    Actor actor = (Actor) object;
236	                    if (actor.getIsAlive())
237	                    {
238	                        boolean canHit = !TimeSystem.isNightTime()
239	                                      || rand.nextDouble() <= 1.0 - NIGHT_PREY_MISS_PROBABILITY;
240	                        if (canHit)
241	                            return eat(actor, newActors);
242	                    }
243	                }
244	            }
245	
246	            if (object instanceof Carcass carcass && canEatCarcass)
247	            {
248	                if (carcass.isDiseased()) infect();
249	                sustenanceLevel += carcass.getConsumptionWorth();
250	                carcass.setDead();
251	                return where;
252	            }
253	        }
254	
255	        return null;
256	    }
257	
258	    @Override
259	    protected boolean becomeCarcass()
260	    {
261	        return true;
262	    }
263	
264	    /**
265	     * Makes the animal eat the food and generate a carcass if necessary.
266	     * @param actor The actor who is to be eaten.
267	     */
268	    private Location eat(Actor actor, List<Actor> newActors)
269	    {
270	        Location location = actor.getLocation();
271	        int actorConsumptionWorth = actor.getConsumptionWorth();
272	        if (actor.becomeCarcass())
273	        {
274	            actor.setDead();
275	            if ((sustenanceLevel + actorConsumptionWorth) > maxSustenanceLevel)
276	            {
277	                int foodLeft = (sustenanceLevel + getConsumptionWorth()) - maxSustenanceLevel;
278	                sustenanceLevel = maxSustenanceLevel;
279	                newActors.add(new Carcass(getField(), location, foodLeft));
280	                return getLocation();
281	            }
282	        }
283	        if (sustenanceLevel + actorConsumptionWorth <= maxSustenanceLevel)
284	        {
285	            sustenanceLevel += actorConsumptionWorth;
286	            return location;
287	        }
288	        return null;
289	    }
290	}
